mapper.select:
SELECT apr41_open_history_id                                                    AS open_history_id
     , TO_CHAR(apr41_open_date, 'YYYY.MM.DD HH24:MI:SS')                        AS open_date_str
     , f_get_empTrans(apr41_person_id, apr41_open_date::date, 'org_code_nm')    AS org_name
     , f_emp_kor_nm(apr41_person_id)                                            AS person_name
     , f_cdnm('LoginModeCode', apr41_login_mode, 0, f_sysdate())                AS login_mode_name
  FROM apr41_open_history
 WHERE apr41_appr_id = #{c.apprId}
 ORDER BY apr41_open_date DESC
 LIMIT #{c.limit}
OFFSET #{c.offset}

SELECT COUNT(*)
  FROM apr41_open_history
 WHERE apr41_appr_id = #{apprId}

SELECT apr42_comment_id   AS comment_id
     , apr42_person_id    AS person_id
     , apr42_comment      AS comment
     , NULL               AS comment_full_str
     , NULL               AS file_str
     , NULL               AS delete_str
  FROM apr42_comment
 WHERE apr42_comment_id = #{commentId}
   AND apr42_appr_id = #{apprId}
   AND apr42_company_id = #{companyId}

mapper.delete:
DELETE FROM apr42_comment
 WHERE apr42_comment_id = #{commentId}
   AND apr42_company_id = #{companyId}
